import{_ as p,a0 as o,w as d,s as r,ao as l,I as t,x as i,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"改变我使用 Git 工作方式的七个技巧 | LCTT x X-CMD","titleTemplate":false,"description":"改变我使用 Git 工作方式的七个技巧 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"改变我使用 Git 工作方式的七个技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"改变我使用 Git 工作方式的七个技巧 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201026 7 Git tricks that changed my life","title":"改变我使用 Git 工作方式的七个技巧","tag":"202012","desc":""},"relativePath":"202012/20201026 7 Git tricks that changed my life.md","filePath":"[post].md"}'),g={name:"202012/20201026 7 Git tricks that changed my life.md"};function h(k,s,u,b,c,f){const a=o("Link");return d(),r("div",null,[s[36]||(s[36]=l(`<h1 id="改变我使用-git-工作方式的七个技巧" tabindex="-1">改变我使用 Git 工作方式的七个技巧 <a class="header-anchor" href="#改变我使用-git-工作方式的七个技巧" aria-label="Permalink to “改变我使用 Git 工作方式的七个技巧”">​</a></h1><blockquote><p>这些有用的技巧将改变你使用这个流行的版本控制系统的工作方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/07/092803d67fa7bttuuj98fb.jpg" alt=""></p><p>Git 是目前最常见的版本控制系统之一，无论是私有系统还是公开托管的网站，都在使用它进行各种开发工作。但无论我对 Git 的使用有多熟练，似乎总有一些功能还没有被发现，下面是改变我使用 Git 工作方式的七个技巧。</p><h3 id="_1、git-中的自动更正" tabindex="-1">1、Git 中的自动更正 <a class="header-anchor" href="#_1、git-中的自动更正" aria-label="Permalink to “1、Git 中的自动更正”">​</a></h3><p>我们有时都会打错字，但如果启用了 Git 的自动更正功能，就可以让 Git 自动修正打错的子命令。</p><p>假设你想用 <code>git status</code> 检查状态，却不小心输入了 <code>git stats</code>。正常情况下，Git 会告诉你 <code>stats</code> 不是一条有效的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The most similar command is</span></span>
<span class="line"><span>status</span></span></code></pre></div><p>为了避免类似的情况发生，请在 Git 配置中启用 Git 自动更正功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global help.autocorrect 1</span></span></code></pre></div><p>如果你希望这个命令只适用于你当前的版本库，请省略 <code>--global</code> 选项。</p>`,11)),t("p",null,[s[1]||(s[1]=i("这条命令启用了自动更正功能。更深入的教程可以在 ",-1)),e(a,{href:"https://git-scm.com/book/en/v2/Customizing-Git-Git-Configuration#_code_help_autocorrect_code"},{default:n(()=>[...s[0]||(s[0]=[i("Git Docs",-1)])]),_:1}),s[2]||(s[2]=i(" 中找到，但尝试一下和上面一样的错误命令，就能很好地了解这个配置的作用：",-1))]),s[37]||(s[37]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span>On branch master</span></span>
<span class="line"><span>Your branch is up to date with ‘origin/master’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nothing to commit, working tree clean</span></span></code></pre></div><p>Git 现在不会建议使用其他子命令，而是直接运行最上面的建议，在本例中是 <code>git status</code>。</p><h3 id="_2、计算你的提交量" tabindex="-1">2、计算你的提交量 <a class="header-anchor" href="#_2、计算你的提交量" aria-label="Permalink to “2、计算你的提交量”">​</a></h3><p>你需要计算提交数量可能有很多原因。例如，许多开发者通过计算提交数量来判断何时该增加构建版本号，或者只是想了解项目的进展情况。</p><p>要计算提交数量其实很简单直接，下面是 Git 的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --count branch-name</span></span></code></pre></div><p>在上面的命令中，<code>branch-name</code> 应该是当前版本库中有效的分支名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –count master</span></span>
<span class="line"><span>32</span></span>
<span class="line"><span>$ git rev-list –count dev</span></span>
<span class="line"><span>34</span></span></code></pre></div><h3 id="_3、优化你的仓库" tabindex="-1">3、优化你的仓库 <a class="header-anchor" href="#_3、优化你的仓库" aria-label="Permalink to “3、优化你的仓库”">​</a></h3>`,9)),t("p",null,[s[4]||(s[4]=i("你的代码仓库不仅对你有价值，对你的组织也有价值。你可以通过一些简单的做法来保持你的版本库的清洁和更新。其中一个最好的做法是 ",-1)),e(a,{href:"https://linux.cn/article-12524-1.html"},{default:n(()=>[...s[3]||(s[3]=[i("使用 .gitignore 文件",-1)])]),_:1}),s[5]||(s[5]=i("。使用这个文件，就是告诉 Git 不要存储许多不需要的文件，比如二进制文件、临时文件等等。",-1))]),s[38]||(s[38]=l(`<p>为了进一步优化你的版本库，你可以使用 Git 的垃圾收集功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git gc --prune=now --aggressive</span></span></code></pre></div><p>当你或你的团队大量使用 <code>pull</code> 或 <code>push</code> 命令时，这条命令就会起到帮助作用。</p><p>这个命令是一个内部工具，可以清理仓库中无法访问或 “孤儿” Git 对象。</p><h3 id="_4、备份未被跟踪的文件" tabindex="-1">4、备份未被跟踪的文件 <a class="header-anchor" href="#_4、备份未被跟踪的文件" aria-label="Permalink to “4、备份未被跟踪的文件”">​</a></h3><p>大多数时候，删除所有未被跟踪的文件是安全的。不过很多时候，你不仅要删除，还要为你的未跟踪文件创建一个备份，以备以后需要。</p><p>通过 Git 和一些 Bash 命令管道，可以很容易地为你的未被跟踪的文件创建一个压缩包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git ls-files --others --exclude-standard -z |\\</span></span>
<span class="line"><span>xargs -0 tar rvf ~/backup-untracked.zip</span></span></code></pre></div><p>上面的命令制作了一个名为 <code>backup-untracked.zip</code> 的存档（并排除了 <code>.gitignore</code> 中列出的文件）。</p><h3 id="_5、了解你的-git-文件夹" tabindex="-1">5、了解你的 .git 文件夹 <a class="header-anchor" href="#_5、了解你的-git-文件夹" aria-label="Permalink to “5、了解你的 .git 文件夹”">​</a></h3><p>每个版本库都有一个 <code>.git</code> 文件夹。它是一个特殊的隐藏文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>. … .git</span></span></code></pre></div><p>Git 的工作主要依赖于两个部分：</p><ol><li>工作树（你当前签出的文件状态）。</li><li>你的 Git 仓库的路径（即你的 <code>.git</code> 文件夹的位置，其中包含版本信息）。</li></ol><p>这个文件夹存储了所有的引用和其他重要的细节，比如配置、仓库数据、HEAD 状态、日志等等。</p><p>如果你删除这个文件夹，你的源代码的当前状态不会被删除，但你的远程信息，如你的项目历史记录，会被删除。删除这个文件夹意味着你的项目（至少是本地副本）不再处于版本控制之下。这意味着你不能跟踪你的变化；你不能从远程拉取或推送。</p><p>一般来说，不需要在 <code>.git</code> 文件夹里做什么，也没有什么应该做的。它是由 Git 管理的，基本上被认为是个禁区。然而，这个目录里有一些有趣的工件，包括 HEAD 的当前状态。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/HEAD</span></span>
<span class="line"><span>ref: refs/heads/master</span></span></code></pre></div><p>它还可能包含对你的存储库的描述：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/description</span></span></code></pre></div><p>这是一个未命名的仓库，编辑这个 <code>description</code> 文件可以命名这个仓库。</p>`,21)),t("p",null,[s[7]||(s[7]=i("Git 钩子文件夹（",-1)),s[8]||(s[8]=t("code",null,"hooks",-1)),s[9]||(s[9]=i("）也在这里，里面有一些钩子示例文件。你可以阅读这些示例来了解通过 Git 钩子可以实现什么，你也可以 ",-1)),e(a,{href:"https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6"},{default:n(()=>[...s[6]||(s[6]=[i("阅读 Seth Kenlon 的 Git 钩子介绍",-1)])]),_:1}),s[10]||(s[10]=i("。",-1))]),s[39]||(s[39]=t("h3",{id:"_6、查看另一个分支的文件",tabindex:"-1"},[i("6、查看另一个分支的文件 "),t("a",{class:"header-anchor",href:"#_6、查看另一个分支的文件","aria-label":"Permalink to “6、查看另一个分支的文件”"},"​")],-1)),s[40]||(s[40]=t("p",null,"有时你想查看另一个分支的文件的内容。用一个简单的 Git 命令就可以实现，而且不需要切换分支。",-1)),t("p",null,[s[12]||(s[12]=i("假设你有一个名为 ",-1)),e(a,{href:"http://README.md"},{default:n(()=>[...s[11]||(s[11]=[i("README.md",-1)])]),_:1}),s[13]||(s[13]=i(" 的文件，它在 ",-1)),s[14]||(s[14]=t("code",null,"main",-1)),s[15]||(s[15]=i(" 分支中，而你正在 ",-1)),s[16]||(s[16]=t("code",null,"dev",-1)),s[17]||(s[17]=i(" 分支上工作。",-1))]),s[41]||(s[41]=l(`<p>使用下面的 Git 命令，你可以在终端上完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show main:README.md</span></span></code></pre></div><p>一旦你执行了这个命令，你就可以在你的终端上查看文件的内容。</p><h3 id="_7、在-git-中搜索" tabindex="-1">7、在 Git 中搜索 <a class="header-anchor" href="#_7、在-git-中搜索" aria-label="Permalink to “7、在 Git 中搜索”">​</a></h3><p>只需一个简单的命令，你就可以像专业人士一样在 Git 中搜索。更棒的是，即使你不确定是在哪个提交或分支上做的修改，也可以在 Git 中搜索。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --all | xargs git grep -F &#39;string&#39;</span></span></code></pre></div><p>例如，假设你想在你的版本库中搜索 <code>font-size: 52 px;</code> 这个字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –all | xargs git grep -F &#39;font-size: 52 px;&#39;</span></span>
<span class="line"><span>F3022…9e12:HtmlTemplate/style.css: font-size: 52 px;</span></span>
<span class="line"><span>E9211…8244:RR.Web/Content/style/style.css: font-size: 52 px;</span></span></code></pre></div><h3 id="试试这些技巧" tabindex="-1">试试这些技巧 <a class="header-anchor" href="#试试这些技巧" aria-label="Permalink to “试试这些技巧”">​</a></h3><p>希望这些高级技巧对你有用，提高你的工作效率，为你节省很多时间。</p>`,10)),t("p",null,[s[19]||(s[19]=i("你有喜欢的 ",-1)),e(a,{href:"https://acompiler.com/git-tips/"},{default:n(()=>[...s[18]||(s[18]=[i("Git 小技巧",-1)])]),_:1}),s[20]||(s[20]=i(" 吗？在评论中分享吧。",-1))]),s[42]||(s[42]=t("hr",null,null,-1)),t("p",null,[s[22]||(s[22]=i("via: ",-1)),e(a,{href:"https://opensource.com/article/20/10/advanced-git-tips"},{default:n(()=>[...s[21]||(s[21]=[i("https://opensource.com/article/20/10/advanced-git-tips",-1)])]),_:1})]),t("p",null,[s[27]||(s[27]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/acompiler"},{default:n(()=>[...s[23]||(s[23]=[i("Rajeev Bera",-1)])]),_:1}),s[28]||(s[28]=i(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[24]||(s[24]=[i("lujun9972",-1)])]),_:1}),s[29]||(s[29]=i(" 译者：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[25]||(s[25]=[i("wxy",-1)])]),_:1}),s[30]||(s[30]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[26]||(s[26]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[33]||(s[33]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[31]||(s[31]=[i("LCTT",-1)])]),_:1}),s[34]||(s[34]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[32]||(s[32]=[i("Linux中国",-1)])]),_:1}),s[35]||(s[35]=i(" 荣誉推出",-1))])])}const x=p(g,[["render",h]]);export{C as __pageData,x as default};
